import{_ as a,a as n}from"./chunks/mmad_hf32_950.BVkfS9LD.js";import{_ as p,o as e,a as c,b as t}from"./app.DKoEZOcr.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"mmad计算关键特性说明","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/mmad_compute_key_features"},{"text":"HF32","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/hf32"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/hf32.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/hf32.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1787967772000}'),o={name:"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/hf32.md"};function l(_,s,d,m,i,r){return e(),c("div",null,[...s[0]||(s[0]=[t('<div><article class="markdown-body"><h1>HF32</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>HF32的核心功能体现为：用户在输入矩阵A和B都为<code>fp32</code>数据类型的场景下，当配置开启HF32开关后，<code>fp32</code>数据在执行矩阵乘法运算前会被转换并舍入为HF32（half-fp32）格式。这种做法可使<a href="../mmad_compute/mmad.html"><code>mmad</code></a>（<code>fp32</code>-&gt;<code>fp32</code>）接口的计算性能提升至原来的两倍，但会带来一定的精度损失。需要注意的是，尽管中间计算使用HF32格式，最终的运算结果仍以<code>fp32</code>格式输出，以保证后续处理的兼容性。</p><blockquote><p><strong>注意：</strong> 启用HF32会引入精度损失，<code>fp32</code>输入数据会在矩阵乘法运算前转换并舍入为HF32格式。</p></blockquote><p>舍入模式说明：<code>fp32</code>至<code>HF32</code>转换过程中的舍入模式由<a href="../../../c_api/cube_compute/asc_set_hf32_round_mode.html"><code>asc_set_hf32_round_mode</code></a>接口配置。当<code>HF32</code>模式开启且舍入模式为<code>asc_hf32_round_mode::NEAREST_AWAY</code>时，则<code>FP32</code>将以向最接近的值舍入，平局时远离零的方式舍入为<code>HF32</code>；若舍入模式为<code>asc_hf32_round_mode::NEAREST_EVEN</code>时，则<code>FP32</code>将以向最接近的值舍入，平局时向偶数舍入的方式舍入为<code>HF32</code>。</p><p><strong>图1</strong> HF32数值精度示意图<a id="zh_cn_topic_mmad_keyfunc_section1_figure1"></a></p><p><img src="'+a+'" alt="HF32数值精度示意图" title="HF32数值精度示意图"></p><div data-filter="950"><p>注意，针对Ascend 950PR/Ascend 950DT产品，其HF32格式的尾数位为10位，示意图如图2所示：</p><p><strong>图2</strong> Ascend 950PR/Ascend 950DT产品HF32数值精度示意图<a id="zh_cn_topic_mmad_keyfunc_section1_figure2"></a></p><p><img src="'+n+`" alt="Ascend 950PR/Ascend 950DT产品HF32数值精度示意图" title="Ascend 950PR/Ascend 950DT产品HF32数值精度示意图"></p></div><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>HF32适用于输入矩阵A和B均为<code>fp32</code>数据类型的<code>mmad</code>（<code>fp32</code>-&gt;<code>fp32</code>）场景。</li><li>使用HF32模式前，需要通过<a href="../../../c_api/cube_compute/asc_enable_hf32.html">asc_enable_hf32</a>开启HF32模式；<code>fp32</code>至HF32转换过程中的舍入模式由<a href="../../../c_api/cube_compute/asc_set_hf32_round_mode.html">asc_set_hf32_round_mode</a>配置。</li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>使用<a href="../../../c_api/cube_compute/asc_enable_hf32.html">asc_enable_hf32</a>开启HF32模式，使用<a href="../../../c_api/cube_compute/asc_set_fp32_mode.html">asc_set_fp32_mode</a>关闭HF32模式，使用<a href="../../../c_api/cube_compute/asc_set_hf32_round_mode.html">asc_set_hf32_round_mode</a>配置舍入模式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>

<span class="c1">// 开启HF32模式</span>
<span class="n">asc_enable_hf32</span><span class="p">();</span>
<span class="c1">// 设置舍入模式为向最接近的值舍入，平局时远离零的方式舍入为HF32</span>
<span class="n">asc_set_hf32_round_mode</span><span class="p">(</span><span class="n">asc_hf32_round_mode</span><span class="o">::</span><span class="n">NEAREST_AWAY</span><span class="p">);</span>
<span class="c1">// mmad计算代码</span>
<span class="n">mmad_params</span><span class="w"> </span><span class="nf">params</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">unit_flag_mode</span><span class="o">::</span><span class="n">disable</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mmad</span><span class="p">(</span><span class="n">mmad_operation</span><span class="p">{},</span><span class="w"> </span><span class="n">mmad_trait_default</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">params</span><span class="p">);</span>
<span class="n">mmad</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">,</span><span class="w"> </span><span class="n">l0a</span><span class="p">,</span><span class="w"> </span><span class="n">l0b</span><span class="p">);</span>

<span class="c1">// 关闭HF32模式</span>
<span class="n">asc_set_fp32_mode</span><span class="p">();</span>
</code></pre></div></article></div>`,1)])])}const A=p(o,[["render",l]]);export{u as __pageData,A as default};
